<?php require '../config/auth.php';login_required('admin');$page_title='Companies';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['company_id'];$act=$_POST['action'];$q=$pdo->prepare('SELECT user_id,company_name FROM companies WHERE id=?');$q->execute([$id]);$c=$q->fetch();if($c){$status=$act==='approve'?'approved':'rejected';$pdo->prepare('UPDATE companies SET approval_status=? WHERE id=?')->execute([$status,$id]);$pdo->prepare('UPDATE users SET status=? WHERE id=?')->execute([$status==='approved'?'active':'inactive',$c['user_id']]);notify($c['user_id'],'Company approval update','Your company registration was '.$status.'.');flash('Company status updated.');}go('companies.php');}$rows=$pdo->query('SELECT c.*,u.email FROM companies c JOIN users u ON u.id=c.user_id ORDER BY c.created_at DESC')->fetchAll();require '../config/header.php';flashes();?><div class="head"><div><h1>Company Management</h1><p>Approve or reject recruiter registrations.</p></div></div><div class="card tablewrap"><table class="table"><tr><th>Company</th><th>Email</th><th>Industry</th><th>HR</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['company_name'])?></td><td><?=e($r['company_email'])?></td><td><?=e($r['industry'])?></td><td><?=e($r['hr_name'])?></td><td><span class="badge <?=$r['approval_status']==='approved'?'green':($r['approval_status']==='rejected'?'red':'orange')?>"><?=e($r['approval_status'])?></span></td><td><form method="post" style="display:flex;gap:5px"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="company_id" value="<?=$r['id']?>"><button class="btn success sm" name="action" value="approve">Approve</button><button class="btn danger sm" name="action" value="reject">Reject</button></form></td></tr><?php endforeach;?></table></div><?php require '../config/footer.php';?>
